CREATE TABLE BILLING_CYCLE (CYCLE_ID VARCHAR2(36) PRIMARY KEY, CYCLE_CODE VARCHAR2(30) NOT NULL UNIQUE, CUT_OFF_DAY NUMBER(2) NOT NULL, DUE_DAYS NUMBER(3) NOT NULL, STATUS VARCHAR2(20) NOT NULL);
CREATE TABLE BILL (BILL_ID VARCHAR2(36) PRIMARY KEY, ACCOUNT_ID VARCHAR2(36) NOT NULL, PRODUCT_CODE VARCHAR2(40) NOT NULL, BILLING_PERIOD VARCHAR2(20) NOT NULL, BUSINESS_DATE DATE NOT NULL, STATUS VARCHAR2(20) NOT NULL, PREVIOUS_BALANCE NUMBER(19,4) NOT NULL, TOTAL_DUE NUMBER(19,4) NOT NULL, MINIMUM_DUE NUMBER(19,4) NOT NULL, PAYMENT_DUE_DATE DATE NOT NULL, CURRENCY_CODE CHAR(3) NOT NULL, VERSION_NO NUMBER(19) DEFAULT 0 NOT NULL, GENERATED_AT TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT UQ_BILL_ACCOUNT_PERIOD UNIQUE (ACCOUNT_ID, BILLING_PERIOD));
CREATE TABLE BILL_LINE (LINE_ID VARCHAR2(36) PRIMARY KEY, BILL_ID VARCHAR2(36) NOT NULL, LINE_TYPE VARCHAR2(30) NOT NULL, SOURCE_REFERENCE VARCHAR2(160) NOT NULL, DESCRIPTION VARCHAR2(500) NOT NULL, AMOUNT NUMBER(19,4) NOT NULL, OCCURRED_AT TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT FK_BILL_LINE_BILL FOREIGN KEY (BILL_ID) REFERENCES BILL(BILL_ID), CONSTRAINT UQ_BILL_LINE_SOURCE UNIQUE (BILL_ID, SOURCE_REFERENCE, LINE_TYPE));
CREATE TABLE BILL_CALCULATION_SNAPSHOT (SNAPSHOT_ID VARCHAR2(36) PRIMARY KEY, BILL_ID VARCHAR2(36) NOT NULL UNIQUE, PRODUCT_VERSION VARCHAR2(30) NOT NULL, INTEREST_POLICY_VERSION VARCHAR2(30) NOT NULL, RATE_SNAPSHOT NUMBER(9,6) NOT NULL, FEE_RULES_JSON CLOB, CALCULATED_AT TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT FK_BILL_SNAPSHOT_BILL FOREIGN KEY (BILL_ID) REFERENCES BILL(BILL_ID));
CREATE TABLE BILL_STATUS_HISTORY (HISTORY_ID VARCHAR2(36) PRIMARY KEY, BILL_ID VARCHAR2(36) NOT NULL, FROM_STATUS VARCHAR2(20), TO_STATUS VARCHAR2(20) NOT NULL, REASON_CODE VARCHAR2(40) NOT NULL, CHANGED_AT TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT FK_BILL_HISTORY_BILL FOREIGN KEY (BILL_ID) REFERENCES BILL(BILL_ID));
CREATE TABLE IDEMPOTENCY_RECORD (RECORD_ID VARCHAR2(36) PRIMARY KEY, IDEMPOTENCY_SCOPE VARCHAR2(100) NOT NULL, KEY_HASH VARCHAR2(64) NOT NULL, REQUEST_HASH VARCHAR2(64) NOT NULL, RESOURCE_ID VARCHAR2(36), CREATED_AT TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT UQ_BILL_IDEMPOTENCY UNIQUE (IDEMPOTENCY_SCOPE, KEY_HASH));
CREATE TABLE AUDIT_LOG (AUDIT_ID VARCHAR2(36) PRIMARY KEY, AGGREGATE_ID VARCHAR2(100), ACTION VARCHAR2(80) NOT NULL, OUTCOME VARCHAR2(20) NOT NULL, CORRELATION_ID VARCHAR2(64) NOT NULL, OCCURRED_AT TIMESTAMP WITH TIME ZONE NOT NULL);
